  "summary": [
    "Anchored on early-2026 pace: about 606 Mediterranean deaths by late February 2026 suggests a nontrivial chance of reaching 900 before April if March remains deadly.",
    "Bayesian synthesis yields a posterior of 97% probability, incorporating multiple updates from reporting and contextual factors.",
    "Significant uncertainty remains due to data revisions, weather variability, and policy/SAR dynamics that could either amplify or dampen near-term fatalities."
  ],
  "confidence": "high",
  "narrative": "Starting from the IOM Missing Migrants Project’s early-2026 death pace, each causal factor nudges the probability toward or away from 900 deaths before April. The combination of a persistently high pace and potential reporting revisions supports a high posterior, around 97%, with uncertainty mainly from data lags and environmental/policy changes.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "anchor chosen from the short-term baseline of IOM Missing Migrants Project Mediterranean deaths for 2026, using the observed early-year trajectory as the starting point for near-term forecasting."
    },
    "factor_updates": [
      {
        "factor": "Sustained high early-year death rate",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "With ~606 deaths by February, March would need ~294 more deaths to hit 900; continuing the recent pace makes reaching 900 plausible."
      },
      {
        "factor": "Data reporting lags and revisions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Later-month revisions can increase March totals beyond real-time tallies, raising the likelihood of surpassing 900."
      },
      {
        "factor": "Weather/sea-state-driven variability",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "March sea conditions can either raise or lower crossings; no clear directional bias from month to month."
      },
      {
        "factor": "Year-to-year variability in Mediterranean tolls",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Historical fluctuations suggest substantial near-term uncertainty about trajectory despite a high early-year pace."
      },
      {
        "factor": "Policy crackdown and SAR capacity changes",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Stricter controls could push migrants toward riskier crossings or hinder rescues, increasing fatalities in the near term."
      }
    ],
    "synthesis_rationale": "The 97% posterior is formed by anchoring to the observed early-2026 pace and applying moderate upward shifts from reporting revisions and potential policy/SAR constraints, while accounting for neutral factors like weather variability and year-to-year volatility. Calibration acknowledges possible overconfidence due to correlated factors; uncertainty remains driven by data lags and near-term operational dynamics."
  }
}

